# Beispiel für mapping.map

BESCH_BESONDERHEITEN=Testsystem vorhanden: Ja, Financal Class: (10, 12, 13) = allgemein, (20, 23) = halbprivat, 30 = privat, Fachabteilung (z.B. OHR1A) wird in PV2_41.3 geliefert, CRM-Gpartnummer (SUVA-PID) wird in ZP__6 geliefert, allerdings nur bei Update Patientendaten (nicht Update Falldaten)
#BESCH_LOGIK_ORCHESTRA=
#BESCH_LOGIK_UMSYSTEM=

# Format: Feld-ID=Beschreibung

# Für HL7-Felder:
# PID_5=Patientenname
# PID_7=Geburtsdatum
# OBX_5=Laborwert Resultat

# Für Text-/CSV-Dateien:
# Feld 1=Auftragsnummer
# Feld 2=Kundenname
# Feld 3=Erstellungsdatum

PV1_2 = I=stationaer,O=ambulant
PV2_41.3 = Spitalspezifisches Feld


PV1_3 = Siehe PV1_3.1 bis PV1_3.7
PV1_3.1 = Fachabteilung
PV1_3.2 = Zimmernummer
PV1_3.3 = Bettplatz
PV1_3.4 = Standort
PV1_3.5 = Status des Orts
PV1_3.6 = Art des Aufenthalts
PV1_19 = FID
PV1_3.7 = Gebaeude

ZA__2 = TCPOS-Nummer
ZP__6 = CRM-Partnernummer (SUVA-PID)